from common import *

def make(v):
    p=Paper(2019,v);k=v+2
    p.mc('Logarithm inverse',f'{k+2}^(log_{k+2}{k+5}) утгыг ол.',k+5,'a^(log_a b)=b.')
    p.mc('Matrix multiplication',f'(−{k}  2)·({k+1}; {k+2}) матрицуудын үржвэрийг ол.',-k*(k+1)+2*(k+2),'Мөрийн ба баганын харгалзах гишүүдийг үржүүлээд нэм.')
    p.mc('Inverse trig function',f'[-π/2;π/2] мужид f(x)={k}sin x функцийн урвууг сонго.',f'arcsin(x/{k})','y=k sin x-ээс x=arcsin(y/k).',[f'arccos(x/{k})',f'{k}arcsin x',f'1/({k}sin x)',f'−{k}sin x'])
    p.mc('Set operation',f'{["Шатар ба хөгжим","Робот ба зураг","Уран зохиол ба бүжиг","Сагсан бөмбөг ба теннис","Кино ба гэрэл зураг"][v-1]} дугуйлангийн аль нэгэнд эсвэл хоёуланд бүртгэлтэй сурагчдын олонлогийг ямар үйлдлээр олдог вэ?','Нэгдэл','A∪B нь дор хаяж нэг олонлогт багтах элементүүд.', ['Огтлолцол','Ялгавар','Гүйцээлт','Картезийн үржвэр'])
    p.mc('Derivative',f'y={k}x³−cos x бол y′-ийг ол.',f'{3*k}x²+sin x','Зэрэгт функц ба cos-ийн уламжлалыг хэрэглэ.',[f'{3*k}x²−sin x',f'{k}x²+sin x',f'{3*k}x³+sin x',f'{3*k}x²+cos x'])
    p.mc('3D vector subtraction',f'a=(−{k},−2,3), b=(1,−2,−{k}) бол a−b-г ол.',(-k-1,0,k+3),'Координат бүрээр хас.',[(k+1,0,-k-3),(-k+1,-4,3-k),(-k-1,-4,k+3),(-k,0,3)])
    p.mc('Axial area',f'Радиус {k}, өндөр {k+2} цилиндрийн тэнхлэг огтлолын талбайг ол.',2*k*(k+2),'Тэнхлэг огтлол нь 2r ба h талтай тэгш өнцөгт.')
    data=[12+k,18+k,24+k,26+k,29+k,31+k,34+k,34+k,36+k,42+k,48+k,53+k,61+k,67+k,69+k]
    stems={}
    for a in data:stems.setdefault(str(a//10),[]).append(a%10)
    p.mc('Stem and leaf range','Иш нь аравт, навч нь нэгжийн орон. Дараах иш-навч өгөгдлийн далайцыг ол.',57,'Хамгийн ихээс хамгийн багыг хас: (69+k)−(12+k)=57.',figure={'kind':'stem_leaf','stems':stems,'key':'1|2 = 12'})
    p.mc('Algebra expansion',f'a(√a−{k})(√a+{k})−({k*k//2 if k%2==0 else k*k}−a)²-г хялбарчил.',val(S.expand(x*(x-k*k)-( (k*k//2 if k%2==0 else k*k)-x)**2)).replace('x','a'),'Эхний үржвэр a(a−k²); хоёр дахь квадратыг задла.',[f'a²−{k*k}',f'−{k*k}a',f'{k*k}a+{k**4}',f'2a²−{k*k}a'])
    p.mc('Fractional powers',f't={F((k+1)**2,100)} үед ∛t·⁶√t утгыг ол.',F(k+1,10),'1/3+1/6=1/2 тул √t.')
    p.mc('Complex quadrant',f'z=i^{4*k+2}+{k}i^{4*k+3} комплекс тоо аль мөчид орших вэ?','III','i^(4k+2)=−1, i^(4k+3)=−i; хоёр координат сөрөг.', ['I','II','IV','Тэнхлэг дээр'])
    a=k+4;b=F(3*k+1,k)
    p.mc('Radical rational simplification',f'a={a}, b={b} үед (√a/(√a−√b)−√b/(√a+√b))·(a−b)/(a²+ab) утгыг ол.',F(1,a),'Хаалт дотор (a+b)/(a−b). Нийт үржвэр 1/a.')
    angle=15*v
    ans=S.simplify(S.cos(S.pi*angle/180))
    p.mc('Trig determinant',f'[[sin({90-angle}°), cos({90-angle}°)], [sin({angle}°), cos({angle}°)]] матрицын тодорхойлогчийг ол.',S.cos(2*S.pi*angle/180),'sin(90−θ)cosθ−cos(90−θ)sinθ=cos²θ−sin²θ=cos2θ.',wrong=distinct_from(S.cos(2*S.pi*angle/180),[S.sin(2*S.pi*angle/180),-S.cos(2*S.pi*angle/180),1,S.cos(S.pi*angle/180),S.Rational(1,2),S.Rational(-1,2),-1,S.sqrt(2)/2,0]))
    p.mc('Radical rational domain',f'y=√(({k}x+2)/({k+4}−x)) функцийн тодорхойлогдох мужийг ол.',f'[{F(-2,k)}; {k+4})','Бутархай≥0; хуваарь тэг биш. Тэмдгийн хүснэгт хэрэглэ.',[f'({F(-2,k)}; {k+4}]',f'({k+4}; +∞)',f'(−∞; {F(-2,k)}]',f'[{F(-2,k)}; +∞)'])
    p.mc('Geometric progression',f'∛{k}, ∛({k}x), {4*k} нь өсөх геометр прогресс. q-г ол.',f'2∛{k}','q²=(4k)/∛k=4(∛k)² тул q=2∛k>1.',[f'4∛{k}',f'∛{k}',f'2/∛{k}',f'{4*k}'])
    poly=4*x**3-6*x**2+2*k*x-(k+4)
    p.mc('Remainder theorem',f'P(x)=4x³−6x²+{2*k}x−{k+4}-г 2x−1-д хуваахад гарах үлдэгдлийг ол.',poly.subs(x,S.Rational(1,2)),'Үлдэгдэл нь P(1/2).')
    p.mc('Power integral',f'∫(x+{k})/√x dx-г ол.',f'(2/3)x√x+{2*k}√x+C','x^(1/2)+k x^(−1/2)-г гишүүн бүрээр интегралчил.',[f'(3/2)x√x+{2*k}√x+C',f'(2/3)x√x+{k}√x+C',f'(2/3)x√x−{2*k}√x+C',f'√x+{2*k}x+C'])
    p.mc('Tangent',f'y={k*k*(k+1)}/x муруйн x=−{k} цэг дээрх шүргэгчийг ол.',f'y=−{k+1}x−{2*k*(k+1)}','Налалт −c/x²=−(k+1); цэгийн координатыг шүргэгчийн томьёонд орлуул.',[f'y={k+1}x',f'y=−{k+1}x',f'y={k+1}x−{2*k*(k+1)}',f'y=−{k+1}x+{2*k*(k+1)}'])
    p.mc('Cubic factorization',f'x³+x²−{k*(k+1)}x=0 тэгшитгэлийн шийдүүдийг ол.',f'{{0; {k}; −{k+1}}}','x(x−k)(x+k+1)=0.',[f'{{{k}; −{k+1}}}',f'{{0; −{k}; {k+1}}}',f'{{1; {k}; −{k+1}}}',f'{{0; {k}; {k+1}}}'])
    p.mc('Frustum lateral area',f'Огтлогдсон конусын суурийн радиусууд {k}, {k+6}, өндөр 8. Хажуу гадаргуугийн талбайг ол.',f'{10*(2*k+6)}π','Байгуулагч √(8²+6²)=10; S=π(R+r)l.',[f'{8*(2*k+6)}π',f'{10*(k+6)}π',f'{6*(2*k+6)}π',f'{11*(2*k+6)}π'])
    p.mc('Slope',f'({k},0), (0,−{k+1}) цэгүүдийг дайрсан шулууны налалтыг ол.',F(k+1,k),'Налалт=(−(k+1)−0)/(0−k).')
    cx=k;cy=1;A=(k-1,2);B=(k+1,4);C=(k+2,1);scale=3
    conv=lambda P:(cx+3*(P[0]-cx),cy+3*(P[1]-cy))
    p.mc('Homothety center',f'A{A},B{B},C{C} цэгүүд гомотетоор A′{conv(A)},B′{conv(B)},C′{conv(C)} болов. Төвийг ол.',(cx,cy),'A′=O+3(A−O) тул O=(3A−A′)/2.',[(cx-1,cy),(cx+1,cy),(cx,cy+1),(cx,cy-1)])
    # Opposite angle 120 degrees makes sqrt(a²+b²+ab), with 3:5 sides gives 7.
    p.mc('Cyclic quadrilateral',f'Тойрогт багтсан PQRS дөрвөн өнцөгтийн QR={3*k}, RS={5*k}, ∠QPS=60°. QS диагоналийг ол.',7*k,'∠QRS=120°. Косинусын теоремоор QS²=9k²+25k²+15k²=49k².')
    p.mc('Square pyramid',f'Зөв дөрвөн өнцөгт пирамидын хажуу тал суурьтай 60° өнцөг үүсгэнэ. Суурийн тал {2*k}. Хажуу ирмэгийг ол.',f'{k}√5','Өндөр k√3, төвөөс орой хүртэл k√2; ирмэг √(3k²+2k²).',[f'{k}√3',f'{2*k}√5',f'{k}√2',f'{2*k}'])
    p.mc('Double angle identity',f'cot α=1/{k} бол (1+cos2α+sin2α)/(1−cos2α+sin2α)-г ол.',F(1,k),'Хүртвэр=2cosα(cosα+sinα), хуваарь=2sinα(sinα+cosα).')
    w=[k+2,2*k+7,k+3];mean=F(3*w[0]+9*w[1]+15*w[2],2*sum(w))
    p.mc('Grouped mean',f'0≤x<3, 3≤x<6, 6≤x<9 завсруудын давтамж {w}. Ангийн төвөөр дундажийг тооц (яг утга).',mean,'Ангийн төвүүд 1.5,4.5,7.5; жигнэсэн нийлбэрийг нийт давтамжид хуваана.')
    n=2*k+2
    p.mc('Combinations and factorials',f'C(n,{k})=C(n,{k+2}), n≥{k+2}. Pₙ/Aₙ²-ыг ол.',f'{n-2}!','Биномиал коэффициентүүдийн тэгш хэмээс n=2k+2; n!/[n(n−1)]=(n−2)!.',[f'{n}!',f'{n-1}!',f'{n-3}!',f'{n}!/2'])
    probs=[F(4,10),F(2,10),F(3,10),F(1,10)];xs=[k,k+3,k+1,k-1]
    p.mc('Expectation',f'X утгууд {xs}, харгалзах магадлалууд {list(map(str,probs))}. E(X)-г ол.',sum(a*b for a,b in zip(xs,probs)),'E(X)=Σxp.')
    p.mc('Area bounded by three lines',f'y=(x+{k})/2, y=−2x+{4*k}, y=0 шулуунуудаар үүсэх гурвалжны талбайг ол.',F(9*k*k,5),'x огтлолууд −k,2k; хоёр налуу шулууны уулзварын өндөр 6k/5; S=3k·(6k/5)/2.')
    p.mc('Quartic coefficient comparison',f'x⁴−{(k+1)**2-2}x²+1=(x²+px+1)(x²−qx+1), p>0 бол p+q-г ол.',2*(k+1),'x³ гишүүнээс p=q; x²-оос 2−p²=2−(k+1)².')
    data=[k,k,k+1,k+3,k+6];mean=S.Rational(sum(data),5);sd=S.sqrt(sum((a-mean)**2 for a in data)/5)
    p.mc('Population standard deviation',f'{data} өгөгдлийн стандарт хазайлтыг ол (нийт олонлогийн томьёо).',sd,'Дундаж k+2, квадрат хазайлтын нийлбэр 26; σ=√(26/5).',distinct_from(sd,[S.Rational(26,5),S.sqrt(26)/2,S.sqrt(26)/5,S.sqrt(S.Rational(13,5)),S.sqrt(S.Rational(26,4))]))
    p.mc('3D vector angle',f'a=(0,−{k},−{k}), b=({k},−{k},−{2*k}) векторуудын өнцгийг ол.','30°','cosθ=3k²/(k√2·k√6)=√3/2.', ['45°','60°','90°','150°'])
    # Shift x by k in the official absolute-exponent structure.
    p.mc('Exponential absolute inequality',f'(1/2)^((x−{k})²−7)<2^(3|x−{k}−1|) тэнцэтгэл бишийг бод.',f'(−∞; {k-1}) ∪ ({k+2}; +∞)','u=x−k гэвэл u²+3|u−1|−7>0; u<−1 эсвэл u>2.',[f'({k-1}; {k+2})',f'(−∞; {k-1}]',f'[{k+2}; +∞)','R'])
    p.mc('Parabola divides trapezoid',f'A({k-4},0),B({k-2},8),C({k+2},8),D({k+4},0) трапецийг y=(x−{k})²+4 парабол ямар харьцаатай талбайнуудад хуваах вэ?','2:7','Трапецийн талбай 48. Параболын дээд хэсэг ∫[-2,2](4−u²)du=32/3. Харьцаа (32/3):(112/3)=2:7.', ['3:8','3:11','4:13','5:16'])
    p.mc('Variance',f'X нь {k}, {k+1} утгыг тус бүр 1/2 магадлалаар авна. Var(X)-г ол.',F(1,4),'Хоёр утгын дунджаас хазайлт ±1/2 тул дисперс 1/4.')
    p.mc('Trig equation solution count',f'{k}sin2x−{2*k+1}cos²x=1, x∈[−π;π] тэгшитгэл хэдэн шийдтэй вэ?',4,'cos x=0 шийд биш. t=tan x гэвэл t²−2kt+2k+2=0. k≥3 үед дискриминант эерэг, хоёр өөр t; урт 2π-д тус бүр хоёр шийд.')
    h=k
    p.multi('2.1','Quadratic inverse and intersections',f'f(x)=(x−{h})²+{h}, x≥{h}. Урвуу функц ба хоёр графикийн огтлолцлыг ол.', [('f⁻¹(x)',f'{h}+√(x−{h})'),('Бага x-тэй огтлолцол',(h,h)),('Их x-тэй огтлолцол',(h+1,h+1)),('Огтлолцлын хоорондох зай','√2')],'Функц өсөх тул огтлолцол y=x дээр. u=x−h≥0 гэвэл u²=u; u=0,1.')
    a=10+v
    p.multi('2.2','Shortest distance to square root curve',f'Жимийн хил y=√x, x≥0. Харуулын байр A({a},0). A-гаас хил хүртэлх хамгийн бага зайг ол.', [('Зайн квадрат дахь x коэффициент',1-2*a),('Хамгийн ойр цэгийн x',F(2*a-1,2)),('Хамгийн бага зай',f'√{4*a-1}/2')],'d²=(x−a)²+x. Оргил x=a−1/2≥0; dmin²=a−1/4.',figure={'kind':'curve_and_point','curve':'y=sqrt(x)','point':[a,0]})
    a=F(k+1,10);b=F(k+2,10)
    p.multi('2.3','Independent Bernoulli events',f'Хоёр төхөөрөмж бие биеэсээ үл хамааран чанарын шалгалт давна. Магадлалууд {a}, {b}.', [('Хоёулаа давах',a*b),('Яг нэг нь давах',a*(1-b)+b*(1-a)),('Ядаж нэг нь давах',1-(1-a)*(1-b))],'Үл хамаарах тул үржүүлнэ. Яг нэг нь: p(1−q)+q(1−p). Ядаж нэг нь: 1−(1−p)(1−q).')
    A=(k,1);B=(k,4);C=(k+2,1)
    p.multi('2.4','Rotation matrix',f'A{A},B{B},C{C} гурвалжныг координатын эхийг тойруулан цагийн зүүний эсрэг 90° эргүүл.', [('A′',(-1,k)),('B′',(-4,k)),('C′',(-1,k+2)),('Хувиргалтын матриц','[[0,−1],[1,0]]')],'90° эсрэг эргэлт (x,y)→(−y,x). Матрицын баганууд нь суурь векторуудын дүрс.')
    p.save()

if __name__=='__main__':
    for v in range(1,6):make(v)
